/** Each entry: { code (IATA), city, name, country }. */
export const AIRPORTS = RAW.map(([code, city, name, country]) => ({ code, city, name, country }));

/** Fast lookup by IATA code. */
const BY_CODE = new Map(AIRPORTS.map((a) => [a.code, a]));

/**
 * Major international hubs. Many cities share a name with a small regional
 * field (e.g. "London, Canada" or "Los Angeles, Chile"); boosting these makes
 * the autocomplete surface the airport travellers actually mean, first.
 */
const MAJOR_HUBS = new Set([
  'LAX','JFK','LGA','EWR','ORD','ATL','DFW','DEN','SFO','SEA','MIA','BOS','LAS','IAH','PHX','MCO','HNL',
  'LHR','LGW','LCY','CDG','ORY','AMS','FRA','MUC','MAD','BCN','FCO','ZRH','IST','DUB','LIS','VIE','CPH','ARN','OSL','HEL','BRU','MAN','EDI','ATH','PRG','WAW',
  'DXB','DOH','AUH','SIN','HKG','NRT','HND','ICN','BKK','KUL','DEL','BOM','PEK','PVG','CAN','TPE','MNL','CGK','DPS',
  'SYD','MEL','BNE','PER','ADL','AKL','CHC','NAN',
  'YYZ','YVR','YUL','GRU','GIG','EZE','SCL','LIM','BOG','MEX','CUN','PTY',
  'JNB','CPT','CAI','NBO','ADD','LOS','CMN','TLV',
]);

/** "Sydney (SYD)" display label used in inputs + the dropdown. */
export function airportLabel(a) {
  return `${a.city || a.name} (${a.code})`;
}

/** Look up a single airport by IATA code (uppercase), or null. */
export function airportByCode(code) {
  return BY_CODE.get((code || '').toUpperCase()) || null;
}

/**
 * Rank airports against a free-text query for the autocomplete dropdown.
 * Matches on IATA code, city, and airport name; exact/prefix code and city
 * matches float to the top. Returns at most `limit` results.
 */
export function searchAirports(query, limit = 8) {
  const q = (query || '').trim().toLowerCase();
  if (!q) return [];
  const scored = [];
  for (const a of AIRPORTS) {
    const code = a.code.toLowerCase();
    const city = (a.city || '').toLowerCase();
    const name = (a.name || '').toLowerCase();
    let score = -1;
    if (code === q) score = 100;
    else if (city === q) score = 90;
    else if (code.startsWith(q)) score = 80;
    else if (city.startsWith(q)) score = 70;
    else if (city.includes(q)) score = 50;
    else if (name.toLowerCase().includes(q)) score = 30;
    else if (code.includes(q)) score = 20;
    if (score >= 0) {
      // Float major hubs up, then prefer shorter (i.e. exact) city names.
      if (MAJOR_HUBS.has(a.code)) score += 6;
      scored.push({ a, score, tie: city.length });
    }
  }
  scored.sort((x, y) => y.score - x.score || x.tie - y.tie);
  return scored.slice(0, limit).map((s) => s.a);
}

/**
 * Resolve free-text input to an IATA code. Handles:
 *  - "Sydney (SYD)"  → SYD  (the dropdown format)
 *  - "syd" / "SYD"   → SYD  (bare code)
 *  - "sydney"        → SYD  (city / name match)
 * Returns null if nothing matches.
 */
export function resolveAirportCode(input) {
  if (!input) return null;
  const text = input.trim();

  const paren = text.match(/\(([A-Za-z]{3})\)/);
  if (paren && BY_CODE.has(paren[1].toUpperCase())) return paren[1].toUpperCase();

  const upper = text.toUpperCase();
  if (/^[A-Z]{3}$/.test(upper) && BY_CODE.has(upper)) return upper;

  const hits = searchAirports(text, 1);
  return hits.length ? hits[0].code : null;
}
